  defp insert_defaults do
    now = DateTime.utc_now()

    sizes =
      for size <- CrewProtocol.Sizes.defaults() do
        Map.merge(size, %{
          id: Ecto.UUID.dump!(CrewProtocol.uuid7()),
          inserted_at: now,
          updated_at: now
        })
      end

    repo().insert_all("sizes", dump_ids(sizes))

    repo().insert_all("cache_config", [
      %{
        id: Ecto.UUID.dump!(CrewProtocol.uuid7()),
        enabled_hosts: CrewProtocol.Hosts.names(),
        allowlist: CrewProtocol.Hosts.default_allowlist(),
        parent_enabled: false,
        ca_generation: 1,
        inserted_at: now,
        updated_at: now
      }
      |> dump_row()
    ])
  end

  # Schemaless inserts don't know column types, so each value is encoded
  # here as ecto_sqlite3 would: binary ids as text, arrays as JSON,
  # booleans as 0/1, timestamps as ISO 8601. Postgrex takes them as is.
  defp dump_ids(rows), do: Enum.map(rows, &dump_row/1)

  defp dump_row(row) do
    if repo().__adapter__() == Ecto.Adapters.SQLite3 do
      Map.new(row, fn
        {:id, id} -> {:id, Ecto.UUID.load!(id)}
        {k, v} when is_list(v) -> {k, Jason.encode!(v)}
        {k, v} when is_boolean(v) -> {k, if(v, do: 1, else: 0)}
        {k, %DateTime{} = v} -> {k, DateTime.to_iso8601(v)}
        kv -> kv
      end)
    else
      row
    end
  end
end
